{"claim_parts": ["Receiving Party shall not disclose the fact that the Agreement was agreed", "Receiving Party shall not disclose the fact that the Agreement was negotiated"],
 "evidence": [{"part": 1, "relation": "insufficient", "same_entity": false, "same_scope": false, "quote": "that discussions or negotiations have taken place or are taking place concerning a possible Transaction"}, {"part": 2, "relation": "insufficient", "same_entity": false, "same_scope": false, "quote": "that discussions or negotiations have taken place or are taking place concerning a possible Transaction"}],
 "missing_conditions": [{"part": 2, "text": "The non-disclosure restriction applies only without the prior written consent of the other party, and it concerns negotiations about the Transaction rather than the Agreement itself.", "quote": "without the prior written consent of the other party hereto"}, {"part": 2, "text": "Disclosure compelled by legal process is permitted without liability, subject to notice and cooperation duties.", "quote": "may do so without liability"}]}

{"claim_parts": ["Receiving Party may independently develop information similar to Confidential Information."],
"evidence": [{"part": 1, "relation": "entails", "same_entity": true, "same_scope": true, "quote": "is or was independently developed by you or your Representatives without reference to, incorporation of, or other use of any Confidential Information"}],
"missing_conditions": [{"part": 1, "text": "Independently developed information is excluded from Confidential Information only if it was developed without reference to, incorporation of, or other use of any Confidential Information. The claim omits this condition.", "quote": "without reference to, incorporation of, or other use of any Confidential Information"}]}

{"claim_parts": ["Receiving Party may share some Confidential Information with some third-parties", "Such third-parties include consultants, agents and professional advisors"],
"evidence": [{"part": 1, "relation": "entails", "same_entity": true, "same_scope": true, "quote": "provided that any such information may be disclosed to your officers, directors, employees, affiliates, accountants, attorneys, financial advisors, consultants, other agents or representatives and financing sources"}, {"part": 2, "relation": "entails", "same_entity": true, "same_scope": true, "quote": "provided that any such information may be disclosed to your officers, directors, employees, affiliates, accountants, attorneys, financial advisors, consultants, other agents or representatives and financing sources"}],
"missing_conditions": [{"part": 1, "text": "Disclosure is limited to Representatives who need to know the information for the purpose of evaluating and implementing the Transaction.", "quote": "who need to know such information for the purpose of evaluating and implementing the Transaction"}, {"part": 1, "text": "Representatives must have been informed of the confidential nature of the information and advised that it is to be kept confidential.", "quote": "have been informed of the confidential nature of the Confidential Information, and have been advised that such information is to be kept confidential"}, {"part": 1, "text": "Such persons are Representatives only to the extent the Receiving Party actually furnishes Confidential Information to them.", "quote": "unless (but solely to the extent that) you furnish Confidential Information to them"}, {"part": 1, "text": "Confidential Information may be used solely for the purpose of evaluating and implementing the Transaction.", "quote": "will be used solely for the purpose of evaluating and implementing the Transaction"}, {"part": 2, "text": "Consultants, agents and advisors are covered only when they are Representatives who need to know the information and have been informed of its confidential nature.", "quote": "who need to know such information for the purpose of evaluating and implementing the Transaction"}, {"part": 2, "text": "The Receiving Party is liable for breaches of the Agreement by such Representatives.", "quote": "You agree you will be liable for any breaches of the terms of this Agreement by such Representatives"}]}

{"claim_parts": ["Receiving Party may independently develop information similar to Confidential Information."],
 "evidence": [{"part": 1, "relation": "insufficient", "same_entity": true, "same_scope": false, "quote": "the receiving party may, during and after the term hereof, use in its business any Residual Information"}],
 "missing_conditions": [{"part": 1, "text": "Residual Information is limited to ideas, know-how and techniques retained in unaided memory; an employee's memory is not unaided if the employee intentionally memorized the information.", "quote": "An employee's memory is unaided if the employee has not intentionally memorized the confidential information"}, {"part": 1, "text": "The residuals provision grants no license under the disclosing party's intellectual property rights.", "quote": "Nothing in this paragraph, however, shall be deemed to grant to the receiving party a license"}]}

{"claim_parts": ["The Receiving Party shall destroy or return some Confidential Information.", "The obligation to destroy or return Confidential Information arises upon termination of the Agreement."],
"evidence": [{"part": 1, "relation": "entails", "same_entity": true, "same_scope": true, "quote": "the Receiving Party shall promptly return to the Disclosing Party all Confidential Information in its possession or control"}, {"part": 1, "relation": "entails", "same_entity": true, "same_scope": true, "quote": "promptly destroy or erase all notes, memoranda and other material prepared by the Receiving Party"}, {"part": 2, "relation": "insufficient", "same_entity": true, "same_scope": false, "quote": "Upon the Disclosing Party’s written request, the Receiving Party shall promptly return to the Disclosing Party all Confidential Information in its possession or control"}, {"part": 2, "relation": "insufficient", "same_entity": true, "same_scope": false, "quote": "The termination of this CNDA, or the completion or abandonment of the Permitted Purpose, shall not affect the survival of the non-disclosure obligations under this CNDA"}],
"missing_conditions": [{"part": 1, "text": "The return and destruction obligation is triggered only by the Disclosing Party's written request.", "quote": "Upon the Disclosing Party’s written request,"}, {"part": 2, "text": "The source ties the return and destruction obligation to the Disclosing Party's written request, not to termination of the Agreement.", "quote": "Upon the Disclosing Party’s written request,"}]}

{"claim_parts": ["Receiving Party may share some Confidential Information with some of Receiving Party's employees"],
 "evidence": [{"part": 1, "relation": "insufficient", "same_entity": false, "same_scope": true, "quote": "to any Person other than its Representatives who have a need to know such Confidential Information and who have been informed of the confidential nature of the Confidential Information"}, {"part": 1, "relation": "insufficient", "same_entity": false, "same_scope": false, "quote": "it shall be responsible for any breach of this CNDA by any of its Representatives"}],
 "missing_conditions": [{"part": 1, "text": "Disclosure is permitted only to Representatives who have a need to know the Confidential Information.", "quote": "Representatives who have a need to know such Confidential Information"}, {"part": 1, "text": "Disclosure is permitted only to Representatives who have been informed of the confidential nature of the Confidential Information.", "quote": "who have been informed of the confidential nature of the Confidential Information"}, {"part": 1, "text": "The Agreement does not state that 'Representatives' includes employees, so the claim's 'employees' is not expressly covered.", "quote": "to any Person other than its Representatives"}]}

{"claim_parts": ["The Receiving Party may share some Confidential Information with some third parties.", "The third parties include consultants, agents and professional advisors."],
"evidence": [{"part": 1, "relation": "entails", "same_entity": true, "same_scope": true, "quote": "the Receiving Party shall not disclose any of the Confidential Information or other facts directly related to the Confidential Information to any Person other than its Representatives who have a need to know"}, {"part": 2, "relation": "insufficient", "same_entity": true, "same_scope": false, "quote": "The Receiving Party will also ensure that its Representatives comply with the terms of this CNDA."}],
"missing_conditions": [{"part": 1, "text": "Disclosure is limited to Representatives who have a need to know the Confidential Information and who have been informed of its confidential nature, so the claim's unconditional permission to share is narrower than the source.", "quote": "who have a need to know such Confidential Information and who have been informed of the confidential nature of the Confidential Information"}, {"part": 2, "text": "The source does not define 'Representatives' or list who falls within it; the definition is said to be found at an external URL, so whether consultants, agents or professional advisors are included cannot be determined from the source alone.", "quote": "Definitions can be found at URL: http://www.cpr.ca/en/about-cp/selling-to-cp/information-technology/definitions"}]}

{"claim": {"subject": "Receiving Party's use of Confidential Information", "parts": [{"predicate": "shall not use any Confidential Information for any purpose other than the purposes stated in Agreement", "polarity": "negative", "quantifier": "all", "universal_wording": true, "modality": "certain", "time": null}]},
"evidence": [
{"part": 1, "role": "bears_on_part", "stance": "affirms", "basis": "necessarily_implies", "subject_match": "same", "quote": "The Receiving Party shall not, in any manner, derive any benefit, directly or indirectly, from the Confidential Information or the use of such Confidential Information, for any purpose."},
{"part": 1, "role": "bears_on_part", "stance": "affirms", "basis": "necessarily_implies", "subject_match": "same", "quote": "The Receiving Party agrees not to appropriate for his or her own use or exploit in any way whatsoever any of the Confidential Information disclosed to it by the Disclosing Party."},
{"part": 1, "role": "counterexample", "stance": "denies", "basis": "states", "subject_match": "narrower", "quote": "Notwithstanding the confidentiality obligations contained in Article 2 hereof, the receiving party may, during and after the term hereof, use in its business any Residual Information."}
],
"qualifiers": [
{"part": 1, "relation": "scope_restriction", "claim_part_changed": "subject", "stated_in_claim": false, "text": "Confidential Information is defined as information clearly marked 'Confidential' or clearly intended to be disclosed in confidence, subject to section 2.02, and the claim's 'any Confidential Information' inherits this definition.", "quote": "subject to section 2.02 below any additional information requested by the Supplier and provided by CPR"},
{"part": 1, "relation": "scope_restriction", "claim_part_changed": "subject", "stated_in_claim": false, "text": "Listed categories are excluded from the meaning of Confidential Information for purposes of the agreement, so the claim's 'any Confidential Information' does not reach them.", "quote": "The following shall not, for the purposes of this CNDA, constitute Confidential Information:"},
{"part": 1, "relation": "exception", "claim_part_changed": "predicate", "stated_in_claim": false, "text": "Section 3.11 permits use of Residual Information in the receiving party's business, notwithstanding the Article 2 confidentiality obligations.", "quote": "Notwithstanding the confidentiality obligations contained in Article 2 hereof, the receiving party may, during and after the term hereof, use in its business any Residual Information."},
{"part": 1, "relation": "scope_restriction", "claim_part_changed": "subject", "stated_in_claim": false, "text": "Residual Information is limited to ideas, know-how and techniques retained in the unaided memory of an ordinary person skilled in the art, which narrows the Section 3.11 exception.", "quote": "the ideas, know-how and techniques that would be retained in the unaided memory of an ordinary person skilled in the art"},
{"part": 1, "relation": "incidental_detail", "claim_part_changed": "predicate", "stated_in_claim": false, "text": "The only purpose the agreement itself states is that the parties are in discussion and negotiation for the provision of certain services; no separate clause defines permitted purposes of use.", "quote": "CPR and Supplier are engaged in discussion and negotiating for the provision of certain services"}
],
